import math
from typing import Callable


def _cosine(a: list, b: list) -> float:
    if len(a) != len(b):
        raise ValueError(f'vector length mismatch: {len(a)} vs {len(b)}')
    dot = sum(x * y for x, y in zip(a, b))
    na = math.sqrt(sum(x * x for x in a))
    nb = math.sqrt(sum(y * y for y in b))
    if na == 0 or nb == 0:
        return 0.0
    return dot / (na * nb)


class Searcher:
    def __init__(self, docs: list):
        if not docs:
            raise ValueError('docs must not be empty')
        self._docs = docs

    def search(self, query_embedding: list, k: int = 5) -> list:
        scored = [
            {'id': d['id'], 'text': d['text'], 'score': _cosine(query_embedding, d['embedding'])}
            for d in self._docs
        ]
        scored.sort(key=lambda h: h['score'], reverse=True)
        return scored[:k]

    def search_by_text(self, query: str, embed: Callable[[str], list], k: int = 5) -> list:
        return self.search(embed(query), k)
